<"'!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>Neon Snake</title>
<style>
  :root {
    --bg-0: #05060d;
    --bg-1: #0a0f24;
    --grid: rgba(120, 180, 255, 0.06);
    --grid-strong: rgba(120, 180, 255, 0.12);
    --neon-a: #4dffb8;
    --neon-b: #4dd0ff;
    --neon-c: #ff4d8a;
    --text: #d6e6ff;
    --muted: #7c89a8;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    background: radial-gradient(1200px 800px at 50% 0%, var(--bg-1), var(--bg-0) 60%, #02030a 100%);
    color: var(--text);
    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    overflow: hidden;
    -webkit-font-smoothing: antialiased;
  }
  body {
    display: grid;
    place-items: center;
    padding: 24px;
  }
  .stage {
    position: relative;
    width: min(92vmin, 720px);
    aspect-ratio: 1 / 1;
    border-radius: 22px;
    background:
      linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0) 30%),
      linear-gradient(180deg, #06091a, #03050f);
    box-shadow:
      0 30px 80px rgba(0,0,0,0.55),
      0 0 0 1px rgba(120, 180, 255, 0.12) inset,
      0 0 80px rgba(77, 208, 255, 0.08) inset;
  }
  canvas {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    display: block;
    border-radius: 22px;
  }
  .hud {
    position: absolute;
    top: 16px;
    left: 18px;
    right: 18px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    pointer-events: none;
    font-variant-numeric: tabular-nums;
    text-shadow: 0 0 12px rgba(77, 208, 255, 0.35);
  }
  .hud .panel {
    background: rgba(8, 12, 28, 0.55);
    border: 1px solid rgba(120, 180, 255, 0.18);
    border-radius: 12px;
    padding: 8px 12px;
    backdrop-filter: blur(6px);
  }
  .hud .label {
    font-size: 11px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--muted);
  }
  .hud .value {
    font-size: 20px;
    font-weight: 600;
    color: var(--text);
  }
  .overlay {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    border-radius: 22px;
    background: radial-gradient(circle at 50% 50%, rgba(5, 8, 22, 0.6), rgba(2, 3, 12, 0.92));
    backdrop-filter: blur(4px);
    text-align: center;
    transition: opacity 0.25s ease, transform 0.25s ease;
  }
  .overlay.hidden {
    opacity: 0;
    pointer-events: none;
    transform: scale(0.98);
  }
  .overlay h1 {
    margin: 0 0 8px;
    font-size: clamp(28px, 5vmin, 44px);
    letter-spacing: 0.04em;
    background: linear-gradient(90deg, var(--neon-a), var(--neon-b));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }
  .overlay p {
    margin: 0 0 18px;
    color: var(--muted);
    font-size: 14px;
  }
  .overlay .keys {
    display: flex;
    gap: 8px;
    justify-content: center;
    flex-wrap: wrap;
    margin: 6px 0 18px;
  }
  .overlay kbd {
    font: inherit;
    font-size: 12px;
    padding: 4px 8px;
    border-radius: 6px;
    background: rgba(120, 180, 255, 0.08);
    border: 1px solid rgba(120, 180, 255, 0.18);
    color: var(--text);
  }
  .overlay button {
    appearance: none;
    border: 0;
    cursor: pointer;
    font: inherit;
    color: #02101a;
    background: linear-gradient(90deg, var(--neon-a), var(--neon-b));
    padding: 10px 18px;
    border-radius: 10px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    box-shadow: 0 8px 24px rgba(77, 208, 255, 0.25);
    transition: transform 0.1s ease, box-shadow 0.2s ease;
  }
  .overlay button:hover { transform: translateY(-1px); box-shadow: 0 10px 30px rgba(77, 208, 255, 0.35); }
  .overlay button:active { transform: translateY(0); }
  .foot {
    position: absolute;
    bottom: 12px;
    left: 0;
    right: 0;
    text-align: center;
    color: var(--muted);
    font-size: 11px;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    pointer-events: none;
  }
  @media (max-width: 520px) {
    .hud .value { font-size: 16px; }
    .hud .label { font-size: 10px; }
  }
</style>
</head>
<body>
  <div class="stage" id="stage">
    <canvas id="board" width="600" height="600" aria-label="Snake game board"></canvas>
    <div class="hud">
      <div class="panel">
        <div class="label">Score</div>
        <div class="value" id="score">0</div>
      </div>
      <div class="panel">
        <div class="label">Best</div>
        <div class="value" id="best">0</div>
      </div>
    </div>
    <div class="overlay" id="overlay">
      <div>
        <h1 id="title">Neon Snake</h1>
        <p id="subtitle">Eat the glowing orbs. Don'"'t bite yourself.</p>
        <div class=\"keys\">
          <kbd>&larr; &uarr; &rarr; &darr;</kbd>
          <kbd>W A S D</kbd>
          <kbd>Space</kbd>
          <kbd>P</kbd>
        </div>
        <button id=\"startBtn\">Start</button>
      </div>
    </div>
    <div class=\"foot\">Arrow keys or WASD &middot; Space to pause &middot; P to toggle</div>
  </div>

<script>
(() => {
  const canvas = document.getElementById('board');
  const ctx = canvas.getContext('2d');
  const overlay = document.getElementById('overlay');
  const titleEl = document.getElementById('title');
  const subtitleEl = document.getElementById('subtitle');
  const startBtn = document.getElementById('startBtn');
  const scoreEl = document.getElementById('score');
  const bestEl = document.getElementById('best');

  const COLS = 24;
  const ROWS = 24;
  const STORAGE_KEY = 'neon-snake-best-v1';

  let cell = 0;
  let dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));

  function resize() {
    const rect = canvas.getBoundingClientRect();
    const size = Math.max(1, Math.floor(rect.width * dpr));
    canvas.width = size;
    canvas.height = size;
    cell = size / COLS;
  }
  window.addEventListener('resize', resize);

  const state = {
    snake: [],
    dir: { x: 1, y: 0 },
    pendingDir: { x: 1, y: 0 },
    food: { x: 0, y: 0, hue: 0 },
    score: 0,
    best: Number(localStorage.getItem(STORAGE_KEY) || 0),
    alive: false,
    paused: false,
    acc: 0,
    grow: 0,
    particles: [],
    shockwaves: [],
    flash: 0,
  };
  bestEl.textContent = state.best;

  function placeFood() {
    let x, y, onSnake;
    do {
      x = Math.floor(Math.random() * COLS);
      y = Math.floor(Math.random() * ROWS);
      onSnake = state.snake.some(s => s.x === x && s.y === y);
    } while (onSnake);
    state.food = { x, y, hue: 200 + Math.random() * 80 };
  }

  function reset() {
    const cx = Math.floor(COLS / 2);
    const cy = Math.floor(ROWS / 2);
    state.snake = [
      { x: cx - 2, y: cy },
      { x: cx - 1, y: cy },
      { x: cx,     y: cy },
    ];
    state.dir = { x: 1, y: 0 };
    state.pendingDir = { x: 1, y: 0 };
    state.score = 0;
    state.grow = 0;
    state.stepMs = 130;
    state.acc = 0;
    state.particles.length = 0;
    state.shockwaves.length = 0;
    state.flash = 0;
    placeFood();
    updateScore();
  }

  function updateScore() {
    scoreEl.textContent = state.score;
    if (state.score > state.best) {
      state.best = state.score;
      localStorage.setItem(STORAGE_KEY, String(state.best));
      bestEl.textContent = state.best;
    }
  }

  function spawnBurst(x, y, hue, count) {
    count = count || 18;
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = 0.6 + Math.random() * 1.8;
      state.particles.push({
        x, y,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s,
        life: 0,
        ttl: 600 + Math.random() * 400,
        hue: hue + (Math.random() * 30 - 15),
        size: 2 + Math.random() * 3,
      });
    }
    state.shockwaves.push({ x, y, t: 0, hue });
  }

  function step() {
    state.dir = state.pendingDir;
    const head = state.snake[state.snake.length - 1];
    const nx = (head.x + state.dir.x + COLS) % COLS;
    const ny = (head.y + state.dir.y + ROWS) % ROWS;
    const newHead = { x: nx, y: ny };

    if (state.snake.some(s => s.x === nx && s.y === ny)) {
      die();
      return;
    }

    state.snake.push(newHead);
    if (state.grow > 0) {
      state.grow--;
    } else {
      state.snake.shift();
    }

    if (nx === state.food.x && ny === state.food.y) {
      state.score += 1;
      state.grow += 1;
      state.stepMs = Math.max(60, state.stepMs - 3);
      spawnBurst(nx, ny, state.food.hue);
      state.flash = 1;
      placeFood();
      updateScore();
    }
  }

  function die() {
    state.alive = false;
    spawnBurst(
      state.snake[state.snake.length - 1].x,
      state.snake[state.snake.length - 1].y,
      0,
      36
    );
    showOverlay('Game Over', 'You scored ' + state.score + '. Best ' + state.best + '.', 'Play Again');
  }

  function showOverlay(title, subtitle, btn) {
    titleEl.textContent = title;
    subtitleEl.textContent = subtitle;
    startBtn.textContent = btn;
    overlay.classList.remove('hidden');
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function setDir(x, y) {
    if (x === -state.dir.x && y === -state.dir.y) return;
    if (x === 0 && y === 0) return;
    state.pendingDir = { x: x, y: y };
  }

  function onKey(e) {
    const k = e.key.toLowerCase();
    if (['arrowup','arrowdown','arrowleft','arrowright',' '].indexOf(e.key.toLowerCase()) "'!== -1
        || ['"'w','a','s','d','p'].indexOf(k) "'!== -1) {
      e.preventDefault();
    }
    if (k === '"'arrowup' || k === 'w') setDir(0, -1);
    else if (k === 'arrowdown' || k === 's') setDir(0, 1);
    else if (k === 'arrowleft' || k === 'a') setDir(-1, 0);
    else if (k === 'arrowright' || k === 'd') setDir(1, 0);
    else if (e.key === ' ' || k === 'p') togglePause();
  }
  window.addEventListener('keydown', onKey, { passive: false });

  // Touch / swipe support
  let touchStart = null;
  canvas.addEventListener('touchstart', (e) => {
    const t = e.changedTouches[0];
    touchStart = { x: t.clientX, y: t.clientY };
  }, { passive: true });
  canvas.addEventListener('touchend', (e) => {
    if ("'!touchStart) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStart.x;
    const dy = t.clientY - touchStart.y;
    if (Math.abs(dx) < 18 && Math.abs(dy) < 18) return;
    if (Math.abs(dx) > Math.abs(dy)) setDir(dx > 0 ? 1 : -1, 0);
    else setDir(0, dy > 0 ? 1 : -1);
    touchStart = null;
  }, { passive: true });

  function togglePause() {
    if (!state.alive) return;
    state.paused = !state.paused;
    if (state.paused) showOverlay('"'Paused', 'Press Space to resume.', 'Resume');
    else hideOverlay();
  }

  function startGame() {
    reset();
    state.alive = true;
    state.paused = false;
    hideOverlay();
  }

  startBtn.addEventListener('click', startGame);
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) startGame();
  });

  function drawGrid() {
    const w = canvas.width;
    const h = canvas.height;
    ctx.fillStyle = 'rgba(120, 180, 255, 0.03)';
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(120, 180, 255, 0.06)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = 0; i <= COLS; i++) {
      const p = Math.round(i * cell) + 0.5;
      ctx.moveTo(p, 0);
      ctx.lineTo(p, h);
    }
    for (let j = 0; j <= ROWS; j++) {
      const p = Math.round(j * cell) + 0.5;
      ctx.moveTo(0, p);
      ctx.lineTo(w, p);
    }
    ctx.stroke();
  }

  function drawFood(now) {
    const f = state.food;
    const cx = (f.x + 0.5) * cell;
    const cy = (f.y + 0.5) * cell;
    const pulse = 0.5 + 0.5 * Math.sin(now * 0.006 + f.hue);
    const r = cell * (0.30 + 0.06 * pulse);
    const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r * 2.2);
    grad.addColorStop(0, 'hsla(' + f.hue + ', 100%, 70%, 0.95)');
    grad.addColorStop(0.4, 'hsla(' + f.hue + ', 100%, 55%, 0.45)');
    grad.addColorStop(1, 'hsla(' + f.hue + ', 100%, 45%, 0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(cx, cy, r * 2.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'hsla(' + f.hue + ', 100%, 80%, 1)';
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.55, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawSnake() {
    const n = state.snake.length;
    if (n === 0) return;
    for (let i = 0; i < n; i++) {
      const s = state.snake[i];
      const t = i / Math.max(1, n - 1);
      const isHead = i === n - 1;
      const px = (s.x + 0.5) * cell;
      const py = (s.y + 0.5) * cell;
      const radius = cell * (isHead ? 0.42 : 0.36);
      const hue = 160 + t * 30;
      const glow = isHead ? 28 : 14;
      const pad = 2 * dpr;
      const x0 = s.x * cell + pad;
      const y0 = s.y * cell + pad;
      const size = cell - pad * 2;

      ctx.shadowColor = 'hsla(' + hue + ', 100%, 60%, 0.9)';
      ctx.shadowBlur = glow * dpr;
      const grad = ctx.createLinearGradient(x0, y0, x0 + size, y0 + size);
      grad.addColorStop(0, 'hsla(' + hue + ', 100%, ' + (isHead ? 70 : 60) + '%, 1)');
      grad.addColorStop(1, 'hsla(' + (hue + 20) + ', 100%, ' + (isHead ? 55 : 45) + '%, 1)');
      ctx.fillStyle = grad;
      roundRect(x0, y0, size, size, radius);
      ctx.fill();
      ctx.shadowBlur = 0;

      if (isHead) drawHeadEyes(px, py);
    }
  }

  function drawHeadEyes(px, py) {
    const dir = state.dir;
    const off = cell * 0.16;
    const eyeR = cell * 0.07;
    const ex1 = px + dir.x * off + dir.y * off;
    const ey1 = py + dir.y * off + dir.x * off;
    const ex2 = px + dir.x * off - dir.y * off;
    const ey2 = py + dir.y * off - dir.x * off;
    ctx.fillStyle = 'rgba(2, 6, 18, 0.85)';
    ctx.beginPath();
    ctx.arc(ex1, ey1, eyeR, 0, Math.PI * 2);
    ctx.arc(ex2, ey2, eyeR, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(220, 255, 240, 0.95)';
    ctx.beginPath();
    ctx.arc(ex1 + dir.x * eyeR * 0.3, ey1 + dir.y * eyeR * 0.3, eyeR * 0.45, 0, Math.PI * 2);
    ctx.arc(ex2 + dir.x * eyeR * 0.3, ey2 + dir.y * eyeR * 0.3, eyeR * 0.45, 0, Math.PI * 2);
    ctx.fill();
  }

  function roundRect(x, y, w, h, r) {
    const rr = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
    ctx.lineTo(x + rr, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
    ctx.lineTo(x, y + rr);
    ctx.quadraticCurveTo(x, y, x + rr, y);
    ctx.closePath();
  }

  function drawParticles(dt) {
    for (let i = state.particles.length - 1; i >= 0; i--) {
      const p = state.particles[i];
      p.life += dt;
      if (p.life >= p.ttl) { state.particles.splice(i, 1); continue; }
      p.x += p.vx;
      p.y += p.vy;
      p.vx *= 0.96;
      p.vy *= 0.96;
      const k = 1 - p.life / p.ttl;
      const cx = p.x * cell + cell / 2;
      const cy = p.y * cell + cell / 2;
      ctx.fillStyle = 'hsla(' + p.hue + ', 100%, 65%, ' + (0.7 * k) + ')';
      ctx.shadowColor = 'hsla(' + p.hue + ', 100%, 60%, 0.8)';
      ctx.shadowBlur = 12 * dpr;
      ctx.beginPath();
      ctx.arc(cx, cy, p.size * dpr * k, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.shadowBlur = 0;

    for (let i = state.shockwaves.length - 1; i >= 0; i--) {
      const s = state.shockwaves[i];
      s.t += dt;
      const k = s.t / 500;
      if (k >= 1) { state.shockwaves.splice(i, 1); continue; }
      const cx = (s.x + 0.5) * cell;
      const cy = (s.y + 0.5) * cell;
      ctx.strokeStyle = 'hsla(' + s.hue + ', 100%, 70%, ' + (0.6 * (1 - k)) + ')';
      ctx.lineWidth = 2 * dpr;
      ctx.beginPath();
      ctx.arc(cx, cy, k * cell * 2.2, 0, Math.PI * 2);
      ctx.stroke();
    }
  }

  function drawFlash() {
    if (state.flash <= 0) return;
    state.flash = Math.max(0, state.flash - 0.06);
    ctx.fillStyle = 'rgba(255, 255, 255, ' + (state.flash * 0.08) + ')';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }

  function drawVignette() {
    const w = canvas.width, h = canvas.height;
    const grad = ctx.createRadialGradient(w/2, h/2, Math.min(w,h)*0.35, w/2, h/2, Math.max(w,h)*0.7);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.55)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
  }

  let lastT = performance.now();
  function frame(t) {
    const dt = Math.min(48, t - lastT);
    lastT = t;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawGrid();

    if (state.alive && "'!state.paused) {
      state.acc += dt;
      while (state.acc >= state.stepMs) {
        state.acc -= state.stepMs;
        step();
        if (!state.alive) break;
      }
    }

    drawFood(t);
    drawSnake();
    drawParticles(dt);
    drawVignette();
    drawFlash();

    requestAnimationFrame(frame);
  }

  resize();
  reset();
  showOverlay('"'Neon Snake', \"Eat the glowing orbs. Don't bite yourself.\", 'Start');
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
