      </div>
    </div>
    <div class="overlay" id="overlay">
      <div>
        <h1 id="title">Neon Snake</h1>
        <p id="subtitle">Eat the glowing orbs. Don'"'t bite yourself.</p>
        <div class=\"keys\">
          <kbd>&larr; &uarr; &rarr; &darr;</kbd>
          <kbd>W A S D</kbd>
          <kbd>Space</kbd>
          <kbd>P</kbd>
        </div>
        <button id=\"startBtn\">Start</button>
      </div>
